import{_ as n,o as s,c as t,a3 as e}from"./chunks/framework.bvEHUNtb.js";const g=JSON.parse('{"title":"10 九宫方位","description":"理解洛书、后天八卦与九宫构成的空间坐标系统。","frontmatter":{"title":"10 九宫方位","description":"理解洛书、后天八卦与九宫构成的空间坐标系统。","category":"guide","aliases":["九宫方位","九宫","洛书九宫"]},"headers":[],"relativePath":"topics/traditional-wisdom/symbols/jiu-gong-fang-wei.md","filePath":"topics/traditional-wisdom/symbols/jiu-gong-fang-wei.md","lastUpdated":1786982540000}'),l={name:"topics/traditional-wisdom/symbols/jiu-gong-fang-wei.md"};function p(i,a,r,o,d,c){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="_10-·-九宫方位-时空坐标系的空间底座" tabindex="-1">10 · 九宫方位：时空坐标系的空间底座 <a class="header-anchor" href="#_10-·-九宫方位-时空坐标系的空间底座" aria-label="Permalink to &quot;10 · 九宫方位：时空坐标系的空间底座&quot;">​</a></h1><hr><h2 id="版本与引用说明" tabindex="-1">版本与引用说明 <a class="header-anchor" href="#版本与引用说明" aria-label="Permalink to &quot;版本与引用说明&quot;">​</a></h2><p>本篇主要依据：</p><ul><li>《黄帝内经·灵枢·九宫八风》（先秦至西汉）</li><li>《大戴礼记·明堂》（西汉，戴德编）</li><li>《易纬·乾凿度》（西汉纬书）</li><li>《周易·说卦传》（战国至汉）</li><li>考古参照：<strong>阜阳汉简《太乙九宫占》</strong>（约前165年），现存最早九宫数字实物</li></ul><hr><h2 id="一、体系定位-在知识树中的坐标" tabindex="-1">一、体系定位：在知识树中的坐标 <a class="header-anchor" href="#一、体系定位-在知识树中的坐标" aria-label="Permalink to &quot;一、体系定位：在知识树中的坐标&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>道 → 阴阳 → 四象 → 后天八卦（方位）</span></span>
<span class="line"><span>                         ↓</span></span>
<span class="line"><span>                      九宫方位  ←── 洛书（数字）</span></span>
<span class="line"><span>                         ↓</span></span>
<span class="line"><span>        奇门遁甲 · 大六壬 · 风水 · 择日 · 中医</span></span></code></pre></div><p><strong>一句话定位</strong>：</p><blockquote><p>九宫方位是后天八卦与洛书数字的<strong>空间整合</strong>——<br> 把八个方位 + 中央，编成一套带数字的坐标网格，<br> 是奇门、六壬、风水三大体系共用的<strong>空间操作系统</strong>。</p></blockquote><h2 id="二、原典依据" tabindex="-1">二、原典依据 <a class="header-anchor" href="#二、原典依据" aria-label="Permalink to &quot;二、原典依据&quot;">​</a></h2><h3 id="文献一《黄帝内经·灵枢·九宫八风》——最早完整记载" tabindex="-1">文献一《黄帝内经·灵枢·九宫八风》——最早完整记载 <a class="header-anchor" href="#文献一《黄帝内经·灵枢·九宫八风》——最早完整记载" aria-label="Permalink to &quot;文献一《黄帝内经·灵枢·九宫八风》——最早完整记载&quot;">​</a></h3><p>【原典】《黄帝内经·灵枢》第七十七篇·九宫八风</p><p>【原文】</p><blockquote><p>太一常以冬至之日，居叶蛰之宫四十六日，明日居天留四十六日，明日居仓门四十六日，明日居阴洛四十五日，明日居天宫四十六日，明日居玄委四十六日，明日居仓果四十六日，明日居新洛四十五日，明日复居叶蛰之宫，曰冬至矣。</p></blockquote><p>这段文字描述&quot;太一&quot;（北极星神格化）按九宫顺序巡行一年，每宫对应一个时间段，是九宫<strong>时间属性</strong>的最早系统记载。同篇还载有九宫方位图，与洛书数字完全对应。</p><h3 id="文献二《大戴礼记·明堂》——空间制度的依据" tabindex="-1">文献二《大戴礼记·明堂》——空间制度的依据 <a class="header-anchor" href="#文献二《大戴礼记·明堂》——空间制度的依据" aria-label="Permalink to &quot;文献二《大戴礼记·明堂》——空间制度的依据&quot;">​</a></h3><p>【原典】《大戴礼记》第六十七篇·明堂（西汉，戴德编）</p><p>【原文】</p><blockquote><p>明堂者，古有之也。凡九室，二茅盖，上圆下方。…… 明堂，所以明诸侯尊卑。</p></blockquote><p>明堂是天子祭天、布政的建筑，九室对应九宫，是九宫方位<strong>制度化落地</strong>的实物依据。天子每月居不同宫室，象征与天地节律同步。</p><h3 id="文献三《易纬·乾凿度》——洛书与九宫的数字来源" tabindex="-1">文献三《易纬·乾凿度》——洛书与九宫的数字来源 <a class="header-anchor" href="#文献三《易纬·乾凿度》——洛书与九宫的数字来源" aria-label="Permalink to &quot;文献三《易纬·乾凿度》——洛书与九宫的数字来源&quot;">​</a></h3><p>【原典】《易纬·乾凿度》（西汉纬书，约前1世纪）</p><p>【原文】太一取其数以行九宫，四正四维皆合于十五。</p><p><strong>&quot;皆合于十五&quot;</strong>——这是洛书九宫最核心的数学性质：任意一行、一列、一对角线，三数之和均为15。这不是神秘主义，是<strong>三阶幻方</strong>的数学必然。</p><h3 id="文献四-考古实物——阜阳汉简《太乙九宫占》" tabindex="-1">文献四：考古实物——阜阳汉简《太乙九宫占》 <a class="header-anchor" href="#文献四-考古实物——阜阳汉简《太乙九宫占》" aria-label="Permalink to &quot;文献四：考古实物——阜阳汉简《太乙九宫占》&quot;">​</a></h3><p>1977年安徽阜阳双古堆汉墓出土，墓主为汝阴侯夏侯灶（约卒于公元前165年）。简文完整记载九宫名称、方位与太一巡行规则，与《灵枢·九宫八风》高度吻合，证明九宫体系在西汉初年已完全成型并用于实践。</p><h2 id="三、洛书九宫-数字与方位的完整对应" tabindex="-1">三、洛书九宫：数字与方位的完整对应 <a class="header-anchor" href="#三、洛书九宫-数字与方位的完整对应" aria-label="Permalink to &quot;三、洛书九宫：数字与方位的完整对应&quot;">​</a></h2><h3 id="_3-1-洛书原图" tabindex="-1">3.1 洛书原图 <a class="header-anchor" href="#_3-1-洛书原图" aria-label="Permalink to &quot;3.1 洛书原图&quot;">​</a></h3><p>待补图</p><h3 id="_3-2-九宫完整对应表" tabindex="-1">3.2 九宫完整对应表 <a class="header-anchor" href="#_3-2-九宫完整对应表" aria-label="Permalink to &quot;3.2 九宫完整对应表&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">宫位</th><th style="text-align:center;">洛书数</th><th style="text-align:center;">后天八卦</th><th style="text-align:center;">五行</th><th style="text-align:center;">方位</th><th style="text-align:center;">季节</th><th style="text-align:center;">九宫名（内经）</th></tr></thead><tbody><tr><td style="text-align:center;">一宫</td><td style="text-align:center;"><strong>1</strong></td><td style="text-align:center;">坎☵</td><td style="text-align:center;">水</td><td style="text-align:center;">正北</td><td style="text-align:center;">冬</td><td style="text-align:center;">叶蛰宫</td></tr><tr><td style="text-align:center;">二宫</td><td style="text-align:center;"><strong>2</strong></td><td style="text-align:center;">坤☷</td><td style="text-align:center;">土</td><td style="text-align:center;">西南</td><td style="text-align:center;">夏末</td><td style="text-align:center;">玄委宫</td></tr><tr><td style="text-align:center;">三宫</td><td style="text-align:center;"><strong>3</strong></td><td style="text-align:center;">震☳</td><td style="text-align:center;">木</td><td style="text-align:center;">正东</td><td style="text-align:center;">春</td><td style="text-align:center;">仓门宫</td></tr><tr><td style="text-align:center;">四宫</td><td style="text-align:center;"><strong>4</strong></td><td style="text-align:center;">巽☴</td><td style="text-align:center;">木</td><td style="text-align:center;">东南</td><td style="text-align:center;">春末</td><td style="text-align:center;">阴洛宫</td></tr><tr><td style="text-align:center;">五宫</td><td style="text-align:center;"><strong>5</strong></td><td style="text-align:center;">中央</td><td style="text-align:center;">土</td><td style="text-align:center;">中央</td><td style="text-align:center;">四季</td><td style="text-align:center;">招摇宫</td></tr><tr><td style="text-align:center;">六宫</td><td style="text-align:center;"><strong>6</strong></td><td style="text-align:center;">乾☰</td><td style="text-align:center;">金</td><td style="text-align:center;">西北</td><td style="text-align:center;">秋末</td><td style="text-align:center;">新洛宫</td></tr><tr><td style="text-align:center;">七宫</td><td style="text-align:center;"><strong>7</strong></td><td style="text-align:center;">兑☱</td><td style="text-align:center;">金</td><td style="text-align:center;">正西</td><td style="text-align:center;">秋</td><td style="text-align:center;">仓果宫</td></tr><tr><td style="text-align:center;">八宫</td><td style="text-align:center;"><strong>8</strong></td><td style="text-align:center;">艮☶</td><td style="text-align:center;">土</td><td style="text-align:center;">东北</td><td style="text-align:center;">冬末</td><td style="text-align:center;">天留宫</td></tr><tr><td style="text-align:center;">九宫</td><td style="text-align:center;"><strong>9</strong></td><td style="text-align:center;">离☲</td><td style="text-align:center;">火</td><td style="text-align:center;">正南</td><td style="text-align:center;">夏</td><td style="text-align:center;">上天宫</td></tr></tbody></table><h3 id="_3-3-洛书的数学本质-三阶幻方" tabindex="-1">3.3 洛书的数学本质：三阶幻方 <a class="header-anchor" href="#_3-3-洛书的数学本质-三阶幻方" aria-label="Permalink to &quot;3.3 洛书的数学本质：三阶幻方&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4  9  2</span></span>
<span class="line"><span>3  5  7</span></span>
<span class="line"><span>8  1  6</span></span>
<span class="line"><span></span></span>
<span class="line"><span>横向：4+9+2=15 / 3+5+7=15 / 8+1+6=15</span></span>
<span class="line"><span>纵向：4+3+8=15 / 9+5+1=15 / 2+7+6=15</span></span>
<span class="line"><span>对角：4+5+6=15 / 2+5+8=15</span></span>
<span class="line"><span></span></span>
<span class="line"><span>任意方向，三数之和 = 15</span></span></code></pre></div><p><strong>15的来源</strong>：$$ 1+2+3+4+5+6+7+8+9 = 45 $$ ， $$ 45 \\div 3 = 15 $$</p><p>这是三阶幻方的<strong>唯一解</strong>（旋转和镜像除外）。古人发现这个图案，将其视为宇宙秩序的数字表达——<strong>不是因为神秘，而是因为它是数学上唯一可能的完美对称结构。</strong></p><h2 id="四、九宫的双重属性-空间-×-时间" tabindex="-1">四、九宫的双重属性：空间 × 时间 <a class="header-anchor" href="#四、九宫的双重属性-空间-×-时间" aria-label="Permalink to &quot;四、九宫的双重属性：空间 × 时间&quot;">​</a></h2><h3 id="_4-1-空间属性-方位坐标" tabindex="-1">4.1 空间属性：方位坐标 <a class="header-anchor" href="#_4-1-空间属性-方位坐标" aria-label="Permalink to &quot;4.1 空间属性：方位坐标&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>九宫 = 把平面空间切成 3×3 的九个区块</span></span>
<span class="line"><span></span></span>
<span class="line"><span>应用：</span></span>
<span class="line"><span>  风水  → 宅内九宫分区（哪个区域对应哪个人口）</span></span>
<span class="line"><span>  奇门  → 九宫布局（值符落哪宫，吉凶方位判断）</span></span>
<span class="line"><span>  六壬  → 九宫与十二地支的方位对应</span></span>
<span class="line"><span>  中医  → 人体九宫（脏腑与方位对应）</span></span></code></pre></div><h3 id="_4-2-时间属性-太一巡宫" tabindex="-1">4.2 时间属性：太一巡宫 <a class="header-anchor" href="#_4-2-时间属性-太一巡宫" aria-label="Permalink to &quot;4.2 时间属性：太一巡宫&quot;">​</a></h3><p>依据《灵枢·九宫八风》，太一（北极星）按固定顺序巡行九宫，每年一轮：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>巡行顺序：1 → 8 → 3 → 4 → 9 → 2 → 7 → 6（ → 回1）</span></span>
<span class="line"><span>        坎 →艮 →震 → 巽 →离 → 坤 →兑 → 乾  → 回坎</span></span>
<span class="line"><span></span></span>
<span class="line"><span>对应节气：</span></span>
<span class="line"><span>  1宫（坎）= 冬至</span></span>
<span class="line"><span>  8宫（艮）= 立春</span></span>
<span class="line"><span>  3宫（震）= 春分</span></span>
<span class="line"><span>  4宫（巽）= 立夏</span></span>
<span class="line"><span>  9宫（离）= 夏至</span></span>
<span class="line"><span>  2宫（坤）= 立秋</span></span>
<span class="line"><span>  7宫（兑）= 秋分</span></span>
<span class="line"><span>  6宫（乾）= 立冬</span></span></code></pre></div><p><strong>这就是奇门遁甲&quot;九宫飞泊&quot;的天文来源</strong>——数字在九宫中按规律流动，不是人为规定，而是对太一巡宫的模拟。</p><h2 id="五、五宫居中-为什么-中央-特殊" tabindex="-1">五、五宫居中：为什么&quot;中央&quot;特殊？ <a class="header-anchor" href="#五、五宫居中-为什么-中央-特殊" aria-label="Permalink to &quot;五、五宫居中：为什么&quot;中央&quot;特殊？&quot;">​</a></h2><h3 id="_5-1-五居中央-不主一方" tabindex="-1">5.1 五居中央，不主一方 <a class="header-anchor" href="#_5-1-五居中央-不主一方" aria-label="Permalink to &quot;5.1 五居中央，不主一方&quot;">​</a></h3><ul><li>四正（1·3·7·9）= 子午卯酉 = 四季正位</li><li>四维（2·4·6·8）= 辰戌丑未 = 四季过渡</li><li>五（中央） = 不属于任何方位，统御八方</li></ul><p>这与四象论中&quot;土居中央不主一方&quot;完全对应：</p><blockquote><p>脾者土也，治中央，常以四时长四藏，各十八日寄治，不得独主于时。</p><pre><code>    ——《黄帝内经·素问·太阴阳明论》
</code></pre></blockquote><p><strong>中央五宫 = 土 = 脾 = 枢纽</strong>，是整个系统的调度中心，而非某一具体方位的主宰。</p><h3 id="_5-2-奇门中的五宫特殊规则" tabindex="-1">5.2 奇门中的五宫特殊规则 <a class="header-anchor" href="#_5-2-奇门中的五宫特殊规则" aria-label="Permalink to &quot;5.2 奇门中的五宫特殊规则&quot;">​</a></h3><p>在奇门遁甲中，五宫无星（无固定星曜），值符落五宫时需&quot;寄宫&quot;——</p><ul><li>阳遁寄二宫（坤）</li><li>阴遁寄八宫（艮）</li></ul><p>这不是规则的例外，而是&quot;中央土寄四隅&quot;这一哲学原则的术数落地。</p><h2 id="六、九宫与各术数体系的接口" tabindex="-1">六、九宫与各术数体系的接口 <a class="header-anchor" href="#六、九宫与各术数体系的接口" aria-label="Permalink to &quot;六、九宫与各术数体系的接口&quot;">​</a></h2><h3 id="_6-1-奇门遁甲" tabindex="-1">6.1 奇门遁甲 <a class="header-anchor" href="#_6-1-奇门遁甲" aria-label="Permalink to &quot;6.1 奇门遁甲&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>九宫 = 奇门的空间舞台</span></span>
<span class="line"><span>  → 九星分布九宫（天盘）</span></span>
<span class="line"><span>  → 八门分布八宫（地盘，五宫无门）</span></span>
<span class="line"><span>  → 八神分布八宫</span></span>
<span class="line"><span>  → 三盘叠加 = 完整奇门局</span></span></code></pre></div><h3 id="_6-2-大六壬" tabindex="-1">6.2 大六壬 <a class="header-anchor" href="#_6-2-大六壬" aria-label="Permalink to &quot;6.2 大六壬&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>九宫 → 与十二地支方位结合</span></span>
<span class="line"><span>    → 确定月将、贵人方位</span></span>
<span class="line"><span>    → 判断事件发生的空间方向</span></span></code></pre></div><h3 id="_6-3-风水-玄空飞星" tabindex="-1">6.3 风水（玄空飞星） <a class="header-anchor" href="#_6-3-风水-玄空飞星" aria-label="Permalink to &quot;6.3 风水（玄空飞星）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>九宫飞星 = 洛书数字按时间周期在九宫中流动</span></span>
<span class="line"><span>   → 每20年换一运（三元九运）</span></span>
<span class="line"><span>   → 当运之星落哪宫 = 哪个方位旺</span></span>
<span class="line"><span>   → 宅内布局依此调整</span></span></code></pre></div><h3 id="_6-4-中医-九宫八风" tabindex="-1">6.4 中医（九宫八风） <a class="header-anchor" href="#_6-4-中医-九宫八风" aria-label="Permalink to &quot;6.4 中医（九宫八风）&quot;">​</a></h3><ul><li>九宫方位，对应八种风向</li><li>不同方位来风 = 不同性质的气</li><li>影响不同脏腑</li></ul><blockquote><p>风从其所居之乡来为实风，主生，长养万物；从其冲后来为虚风，伤人者也，主杀，主害者。 ——《灵枢·九宫八风》</p></blockquote><h2 id="七、现代解读-九宫本质上是什么" tabindex="-1">七、现代解读：九宫本质上是什么？ <a class="header-anchor" href="#七、现代解读-九宫本质上是什么" aria-label="Permalink to &quot;七、现代解读：九宫本质上是什么？&quot;">​</a></h2><h3 id="_7-1-最小完备的空间分类系统" tabindex="-1">7.1 最小完备的空间分类系统 <a class="header-anchor" href="#_7-1-最小完备的空间分类系统" aria-label="Permalink to &quot;7.1 最小完备的空间分类系统&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>为什么是9，不是4或16？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4宫（田字格）：只有四个方位，无法表达&quot;过渡区域&quot;</span></span>
<span class="line"><span>16宫（4×4）：过于精细，中腹过大，不均等，信息冗余</span></span>
<span class="line"><span>9宫（3×3）：</span></span>
<span class="line"><span>  → 4个正方位（东南西北）</span></span>
<span class="line"><span>  → 4个过渡方位（东南·西南·东北·西北）</span></span>
<span class="line"><span>  → 1个中央枢纽</span></span>
<span class="line"><span>  = 用最少的格子，覆盖所有空间关系</span></span></code></pre></div><p>这是<strong>信息压缩的最优解</strong>——用9个格子，穷举平面空间的所有基本方位关系。</p><h3 id="_7-2-数字编码的意义" tabindex="-1">7.2 数字编码的意义 <a class="header-anchor" href="#_7-2-数字编码的意义" aria-label="Permalink to &quot;7.2 数字编码的意义&quot;">​</a></h3><p>洛书给每个宫位一个数字（1-9），使得：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>方位 → 可以计算</span></span>
<span class="line"><span>空间关系 → 可以用数字运算表达</span></span>
<span class="line"><span>时间流动 → 可以用数字序列追踪</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这就是&quot;数术&quot;的本质：</span></span>
<span class="line"><span>把时空关系转化为数字，</span></span>
<span class="line"><span>用数字运算模拟时空变化。</span></span></code></pre></div><h3 id="_7-3-与现代矩阵思维的对应" tabindex="-1">7.3 与现代矩阵思维的对应 <a class="header-anchor" href="#_7-3-与现代矩阵思维的对应" aria-label="Permalink to &quot;7.3 与现代矩阵思维的对应&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>洛书九宫 = 一个 3×3 矩阵</span></span>
<span class="line"><span>每个格子有：</span></span>
<span class="line"><span>  → 坐标（行·列）</span></span>
<span class="line"><span>  → 数值（1-9）</span></span>
<span class="line"><span>  → 属性（五行·八卦·方位·时间）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>现代GIS（地理信息系统）的基本单元，也是网格矩阵。</span></span>
<span class="line"><span>古人用九宫做的事，和现代空间分析的底层逻辑，本质相同。</span></span></code></pre></div><h2 id="八、承前启后" tabindex="-1">八、承前启后 <a class="header-anchor" href="#八、承前启后" aria-label="Permalink to &quot;八、承前启后&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上承：</span></span>
<span class="line"><span>  后天八卦（提供方位与五行属性）</span></span>
<span class="line"><span>  洛书（提供数字编码）</span></span>
<span class="line"><span>  二十八星宿（提供天文坐标背景）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>本篇整合：</span></span>
<span class="line"><span>  九宫 = 后天八卦 × 洛书数字 × 太一巡宫时间</span></span>
<span class="line"><span></span></span>
<span class="line"><span>下启：</span></span>
<span class="line"><span>  → 11·十天干（时间坐标的第一维）</span></span>
<span class="line"><span>  → 12·十二地支（时间坐标的第二维）</span></span>
<span class="line"><span>  → 奇门遁甲实战（九宫是操作平台）</span></span>
<span class="line"><span>  → 风水玄空飞星（九宫是布局基础）</span></span></code></pre></div><h2 id="九、本章小结" tabindex="-1">九、本章小结 <a class="header-anchor" href="#九、本章小结" aria-label="Permalink to &quot;九、本章小结&quot;">​</a></h2><p>九宫方位不是一张神秘的图，是一套<strong>最小完备的时空操作系统</strong>：</p><ul><li>🔢 <strong>数字层</strong>：洛书三阶幻方，数学上唯一的完美对称结构</li><li>🧭 <strong>空间层</strong>：九个方位，穷举平面空间的所有基本关系</li><li>📅 <strong>时间层</strong>：太一巡宫，把时间周期编码进空间坐标</li><li>🔗 <strong>接口层</strong>：奇门·六壬·风水·中医，共用这一底座</li></ul><blockquote><p>古人用九宫做的事，是把&quot;我在哪里·现在是什么时候·能量如何流动&quot;<br> 这三个问题，整合进一个统一的坐标框架。<br> 这不是玄学，是<strong>古代的时空信息系统</strong>。</p></blockquote><hr><p><strong>下一篇预告</strong>：<strong>11 · 十天干</strong>——时间坐标系的第一维，五行与阴阳的时间编码，以及鲜为人知的&quot;十月太阳历&quot;来源。</p><hr><p><em>文档版本：v1.0 · 九宫方位 ｜ 2026年7月 ｜ 持续更新中</em></p>`,82)])])}const u=n(l,[["render",p]]);export{g as __pageData,u as default};
